late LocalRepository repository;
final appProvider = ChangeNotifierProvider<AppController>((ref) => AppController(repository));
Future<void> main() async { WidgetsFlutterBinding.ensureInitialized(); await Hive.initFlutter(); repository = LocalRepository(await Hive.openBox('mycar')); runApp(const ProviderScope(child: MyCarApp())); }
class AppController extends ChangeNotifier { AppController(this.repo): vehicle=repo.vehicle, oil=repo.oil, restriction=repo.restriction, pads=repo.pads, fluid=repo.fluid; final LocalRepository repo; Vehicle? vehicle; OilChange? oil; PlateRestriction? restriction; List<BrakePadChange> pads; List<BrakeFluidChange> fluid; Future<void> setVehicle(Vehicle v) async { vehicle=v; await repo.saveVehicle(v); notifyListeners(); } Future<void> setOil(OilChange v) async { oil=v; await repo.saveOil(v); notifyListeners(); } Future<void> setRestriction(PlateRestriction v) async { restriction=v; await repo.saveRestriction(v); notifyListeners(); } Future<void> addPads(BrakePadChange v) async { pads=[v,...pads]; await repo.savePads(pads); notifyListeners(); } Future<void> addFluid(BrakeFluidChange v) async { fluid=[v,...fluid]; await repo.saveFluid(fluid); notifyListeners(); } }
class MyCarApp extends StatelessWidget { const MyCarApp({super.key}); @override Widget build(BuildContext context) => MaterialApp(debugShowCheckedModeBanner:false,title:'myCar',theme:AppTheme.build(Brightness.light),darkTheme:AppTheme.build(Brightness.dark),themeMode:ThemeMode.system,builder:(context,child)=>MediaQuery(data:MediaQuery.of(context).copyWith(textScaler:TextScaler.noScaling),child:child!),home:const AppShell()); }
class AppShell extends ConsumerStatefulWidget { const AppShell({super.key}); @override ConsumerState<AppShell> createState()=>_AppShellState(); }
class _AppShellState extends ConsumerState<AppShell> {
  int tab = 0;
  @override Widget build(BuildContext context) {
    final pages = [const RedesignedDashboard(), const VehiclePage(), const MaintenanceHistoryPage(), const SettingsPage()];
    return Scaffold(
      body: SafeArea(child: pages[tab]),
      floatingActionButton: tab == 0 ? FloatingActionButton(onPressed: () => _quickAdd(context), backgroundColor: AppTheme.teal, foregroundColor: Colors.white, child: const Icon(CupertinoIcons.plus)) : null,
      bottomNavigationBar: NavigationBar(selectedIndex: tab, onDestinationSelected: (v) => setState(() => tab = v), destinations: const [NavigationDestination(icon: Icon(CupertinoIcons.house), label: 'Inicio'), NavigationDestination(icon: Icon(CupertinoIcons.car_detailed), label: 'Mi vehículo'), NavigationDestination(icon: Icon(CupertinoIcons.wrench), label: 'Mantenimiento'), NavigationDestination(icon: Icon(CupertinoIcons.gear), label: 'Ajustes')]),
    );
  }
  void _quickAdd(BuildContext context) => showModalBottomSheet(context: context, showDragHandle: true, builder: (_) => SafeArea(child: Column(mainAxisSize: MainAxisSize.min, children: [ListTile(leading: const Icon(CupertinoIcons.camera_fill, color: AppTheme.teal), title: const Text('Ver estado con cámara'), subtitle: const Text('myCar Vision'), onTap: () { Navigator.pop(context); openCarVision(context); }), ListTile(leading: const Icon(CupertinoIcons.drop_fill, color: AppTheme.teal), title: const Text('Prueba de aceite'), subtitle: const Text('Analiza la foto de la varilla'), onTap: () { Navigator.pop(context); openOilCheck(context); }), ListTile(leading: const Icon(CupertinoIcons.viewfinder_circle_fill, color: AppTheme.teal), title: const Text('Inspección guiada'), subtitle: const Text('Motor, frenos y estado general'), onTap: () { Navigator.pop(context); openGuidedInspection(context); }), ListTile(leading: const Icon(CupertinoIcons.drop_fill), title: const Text('Registrar cambio de aceite'), onTap: () { Navigator.pop(context); showOilForm(context); }), ListTile(leading: const Icon(CupertinoIcons.car_detailed), title: const Text('Actualizar vehículo'), onTap: () { Navigator.pop(context); showVehicleForm(context); })])));
}
class Dashboard extends ConsumerWidget { const Dashboard({super.key}); @override Widget build(BuildContext context,WidgetRef ref) { final app=ref.watch(appProvider); final v=app.vehicle; final oil=app.oil; if(v==null)return _EmptyDashboard(onStart:()=>showVehicleForm(context)); final pending=oil!=null&&oil.currentMileage>=oil.nextMileage; return CustomScrollView(slivers:[SliverPadding(padding:const EdgeInsets.fromLTRB(20,16,20,100),sliver:SliverList(delegate:SliverChildListDelegate([Text('myCar',style:Theme.of(context).textTheme.headlineMedium?.copyWith(fontWeight:FontWeight.w700,letterSpacing:-1)),const SizedBox(height:4),Text(v.label,style:Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.w700)),Text('${VehicleSpecification.localFor(v)?.engine??'Especificaciones por definir'} • ${v.transmission}',style:Theme.of(context).textTheme.bodyMedium?.copyWith(color:Theme.of(context).colorScheme.onSurfaceVariant)),const SizedBox(height:18),const _EngineHero(),const SizedBox(height:18),if(_todayRestriction(app.restriction))const _Warning(),GridView.count(crossAxisCount:2,childAspectRatio:1.3,shrinkWrap:true,physics:const NeverScrollableScrollPhysics(),crossAxisSpacing:12,mainAxisSpacing:12,children:[InfoCard(icon:CupertinoIcons.calendar,label:'PICO Y PLACA',value:app.restriction?.day??'Configurar'),InfoCard(icon:CupertinoIcons.speedometer,label:'KILOMETRAJE',value:'${v.mileage} km'),InfoCard(icon:CupertinoIcons.drop_fill,label:'ACEITE',value:oil==null?'Registrar':pending?'Pendiente':'Próximo: ${oil.nextMileage} km',accent:pending),const InfoCard(icon:CupertinoIcons.wrench,label:'FRENOS',value:'Revisión: 15/12/2026')]),const SizedBox(height:20),Text('Estado del vehículo',style:Theme.of(context).textTheme.titleMedium?.copyWith(fontWeight:FontWeight.w700)),const SizedBox(height:10),Card(child:ListTile(leading:const CircleAvatar(backgroundColor:Color(0x2200AFA5),child:Icon(CupertinoIcons.check_mark_circled_solid,color:AppTheme.teal)),title:const Text('Todo bajo control'),subtitle:Text(oil==null?'Registra tu primer mantenimiento.':pending?'Tu cambio de aceite requiere atención.':'Mantenimiento al día.')))])))]); } }
class _EngineHero extends StatelessWidget { const _EngineHero(); @override Widget build(BuildContext context)=>ClipRRect(borderRadius:BorderRadius.circular(28),child:SizedBox(height:230,width:double.infinity,child:Stack(fit:StackFit.expand,children:[Image.asset('assets/images/futuristic_engine.png',fit:BoxFit.cover,alignment:Alignment.topCenter),const DecoratedBox(decoration:BoxDecoration(gradient:LinearGradient(begin:Alignment.topCenter,end:Alignment.bottomCenter,colors:[Colors.transparent,Color(0x99000000)]))),const Positioned(left:18,bottom:16,child:Text('Tu motor, siempre listo',style:TextStyle(color:Colors.white,fontSize:17,fontWeight:FontWeight.w700)))]))); }
