void showVehicleForm(BuildContext context){final old=ProviderScope.containerOf(context).read(appProvider).vehicle;final brand=TextEditingController(text:old?.brand??'Toyota'),model=TextEditingController(text:old?.model??'Corolla'),year=TextEditingController(text:(old?.year??2022).toString()),km=TextEditingController(text:(old?.mileage??72450).toString()),plate=TextEditingController(text:(old?.plateDigit??3).toString()),version=TextEditingController(text:old?.version??'');String transmission=old?.transmission??'Automático';showModalBottomSheet(context:context,isScrollControlled:true,showDragHandle:true,builder:(ctx)=>Padding(padding:EdgeInsets.fromLTRB(20,0,20,MediaQuery.of(ctx).viewInsets.bottom+24),child:StatefulBuilder(builder:(ctx,setState)=>SingleChildScrollView(child:Column(crossAxisAlignment:CrossAxisAlignment.start,mainAxisSize:MainAxisSize.min,children:[Text('Tu vehículo',style:Theme.of(ctx).textTheme.headlineSmall?.copyWith(fontWeight:FontWeight.w700)),_field(brand,'Marca'),_field(model,'Modelo'),_field(year,'Año',number:true),_field(version,'Versión (opcional)'),_field(km,'Kilometraje actual',number:true),_field(plate,'Último dígito de placa',number:true),const SizedBox(height:8),const Text('¿Tu vehículo es manual o automático?'),SegmentedButton<String>(segments:const [ButtonSegment(value:'Manual',label:Text('Manual')),ButtonSegment(value:'Automático',label:Text('Automático'))],selected:{transmission},onSelectionChanged:(s)=>setState(()=>transmission=s.first)),const SizedBox(height:16),SizedBox(width:double.infinity,child:FilledButton(onPressed:(){ProviderScope.containerOf(context).read(appProvider).setVehicle(Vehicle(brand:brand.text,model:model.text,year:int.tryParse(year.text)??2022,version:version.text,mileage:int.tryParse(km.text)??0,plateDigit:int.tryParse(plate.text)??0,transmission:transmission));Navigator.pop(ctx);},child:const Text('Guardar vehículo')))])))));}
Widget _field(TextEditingController c,String label,{bool number=false})=>Padding(padding:const EdgeInsets.only(top:12),child:TextField(controller:c,keyboardType:number?TextInputType.number:null,decoration:InputDecoration(labelText:label,border:const OutlineInputBorder())));
void showOilForm(BuildContext context){final app=ProviderScope.containerOf(context).read(appProvider);final current=TextEditingController(text:(app.vehicle?.mileage??72450).toString()),last=TextEditingController(text:(app.oil?.lastMileage??65000).toString());int interval=10000;showModalBottomSheet(context:context,isScrollControlled:true,showDragHandle:true,builder:(ctx)=>Padding(padding:EdgeInsets.fromLTRB(20,0,20,MediaQuery.of(ctx).viewInsets.bottom+24),child:StatefulBuilder(builder:(ctx,setState)=>Column(mainAxisSize:MainAxisSize.min,crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Cambio de aceite',style:Theme.of(ctx).textTheme.headlineSmall?.copyWith(fontWeight:FontWeight.w700)),_field(current,'Kilometraje actual',number:true),_field(last,'Kilometraje último cambio',number:true),const SizedBox(height:12),DropdownButtonFormField<int>(value:interval,decoration:const InputDecoration(labelText:'Intervalo recomendado',border:OutlineInputBorder()),items:const [5000,7500,10000].map((i)=>DropdownMenuItem(value:i,child:Text('$i km'))).toList(),onChanged:(v)=>setState(()=>interval=v!)),const SizedBox(height:16),SizedBox(width:double.infinity,child:FilledButton(onPressed:(){app.setOil(OilChange(currentMileage:int.tryParse(current.text)??0,lastMileage:int.tryParse(last.text)??0,interval:interval,date:DateTime.now()));Navigator.pop(ctx);},child:const Text('Guardar cambio')))]))));}
void showRestrictionForm(BuildContext context){final app=ProviderScope.containerOf(context).read(appProvider);String day=app.restriction?.day??'Miércoles';showModalBottomSheet(context:context,showDragHandle:true,builder:(ctx)=>Padding(padding:const EdgeInsets.all(20),child:StatefulBuilder(builder:(ctx,setState)=>Column(mainAxisSize:MainAxisSize.min,crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Pico y placa',style:Theme.of(ctx).textTheme.headlineSmall?.copyWith(fontWeight:FontWeight.w700)),const SizedBox(height:16),DropdownButtonFormField(value:day,items:const ['Lunes','Martes','Miércoles','Jueves','Viernes'].map((d)=>DropdownMenuItem(value:d,child:Text(d))).toList(),onChanged:(v)=>setState(()=>day=v!),decoration:const InputDecoration(labelText:'Día de restricción',border:OutlineInputBorder())),const SizedBox(height:16),SizedBox(width:double.infinity,child:FilledButton(onPressed:(){app.setRestriction(PlateRestriction(digit:app.vehicle?.plateDigit??0,day:day));Navigator.pop(ctx);},child:const Text('Guardar configuración')))]))));}
